#!/usr/bin/env python3
import csv
import os
from collections import defaultdict

# CBSA names to search for
# Good AQI for CO = AQI <= 50 or 1st Max Value <= 4.4 ppm
# According to EPA, CO "Good" range is 0-4.4 ppm for daily max 8-hour average

target_cbsas = [
    "Portland-Vancouver-Hillsboro, OR-WA",
    "Wichita, KS",
    "San Diego-Carlsbad, CA"
]

# For each year, track: for each CBSA, did any monitor on any day have max value > 4.4?
results = {}

for year in range(2000, 2011):
    filepath = f"/tmp/epa_co/daily_42101_{year}.csv"
    if not os.path.exists(filepath):
        print(f"Missing: {filepath}")
        continue

    # Track max values by CBSA
    cbsa_days = defaultdict(dict)  # cbsa -> date -> max_value
    cbsa_found = set()

    with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
        reader = csv.DictReader(f)
        for row in reader:
            cbsa = row.get('CBSA Name', '').strip()
            # Check if this CBSA matches any target
            cbsa_match = None
            for target in target_cbsas:
                if cbsa == target:
                    cbsa_match = target
                    break
            if cbsa_match is None:
                continue

            cbsa_found.add(cbsa_match)
            date = row.get('Date Local', '').strip()

            # Get the 1st max value (the daily maximum concentration)
            try:
                max_val = float(row.get('1st Max Value', '0') or '0')
            except:
                max_val = 0

            # Keep the highest max value for this CBSA/date combo
            if date not in cbsa_days[cbsa_match]:
                cbsa_days[cbsa_match][date] = max_val
            else:
                if max_val > cbsa_days[cbsa_match][date]:
                    cbsa_days[cbsa_match][date] = max_val

    year_results = {}
    for target in target_cbsas:
        if target not in cbsa_found:
            year_results[target] = "NOT FOUND"
        else:
            days = cbsa_days[target]
            max_over_year = max(days.values()) if days else 0
            num_days = len(days)
            bad_days = [(d, v) for d, v in days.items() if v > 4.4]
            year_results[target] = {
                "max_value": max_over_year,
                "num_days": num_days,
                "bad_days": len(bad_days),
                "bad_day_examples": sorted(bad_days)[:3],
                "all_good": len(bad_days) == 0
            }

    results[year] = year_results
    print(f"\n=== Year {year} ===")
    for cbsa, info in year_results.items():
        print(f"  {cbsa}: {info}")

print("\n\n=== SUMMARY: Years where ALL 3 CBSAs had ALL days in 'Good' range (<=4.4 ppm) ===")
good_years = []
for year in range(2000, 2011):
    if year not in results:
        continue
    all_good = True
    for target in target_cbsas:
        info = results[year][target]
        if info == "NOT FOUND" or not info.get("all_good", False):
            all_good = False
            break
    if all_good:
        good_years.append(year)
    print(f"  {year}: {'ALL GOOD' if all_good else 'NOT ALL GOOD'}")

print(f"\nGood years: {good_years}")

